import Foundation

private typealias S = Legal.Section
private let app = Legal.appName, author = Legal.author

enum LegalZH {
    static let agreement: [Legal.Section] = [
        S(id: 1, title: "1. 接受条款", body: "本用户协议（“协议”）规范你对 \(app)（“本应用”）的使用。点击“接受并继续”即表示你已阅读并理解本协议，并同意受其约束。如不同意，请勿使用本应用并将其退出。你确认已成年，并依据所在国家法律具有完全民事行为能力。"),
        S(id: 2, title: "2. 本应用的功能", body: "本应用展示来自第三方来源的货币、股票和加密货币价格；提供“助手”，将近期价格转化为动量信号（BUY、作为做空的 SELL 或 HOLD）、概率、模拟价格情景、止损和目标位以及建议仓位；交易日志；可选的新闻标题及由你选择的 AI 服务生成的摘要；以及（如你选择）公开钱包地址（包括 Telegram 中 Wallet 的 TON 钱包）和通过只读密钥连接的 Binance 账户的余额。本应用只读：它不是经纪商，从不索取私钥、助记词、密码或银行信息，无法下单、签署交易或转移资金。Telegram 中的 Wallet 没有只读 API，因此本应用从不连接 Wallet 账户；Wallet Perps 仓位只来自你放入本应用“收件箱”文件夹的文件。"),
        S(id: 3, title: "3. 不构成投资建议", body: "本应用展示的一切均为自动模型生成的一般信息，不构成金融、投资、税务或法律建议，也不是买入、卖出、做空或持有任何资产的要约或推荐。信号、概率、情景、价位和仓位均是依据历史价格、按固定机械规则和随机模拟计算的估计；它们不了解你的目标、财务状况或风险承受能力，可能出错，过去的表现也不代表未来结果。日内交易和做空风险尤其高：价格可能快速波动，跳空可能越过止损，你的损失可能超出预期。价格可能延迟、不完整或不准确，并可能与你的银行、经纪商或交易所不同。AI 摘要可能错误或过时。请始终通过权威来源核实信息，考虑咨询持牌顾问，并且只用你承受得起损失的资金。"),
        S(id: 4, title: "4. 你的决定", body: "是否交易以及如何交易完全由你决定。任何订单都由你本人在你选择的经纪商或交易所按其条款下达。本应用不会监控你的持仓，也不会在触及止损或目标时提醒你。"),
        S(id: 5, title: "5. 无担保", body: "本应用按“现状”和“现有”提供，不附带任何明示或暗示的担保，包括对准确性、完整性、及时性、适销性、特定用途适用性或不间断运行的担保。数据来源可能随时变更、延迟或停止工作。"),
        S(id: 6, title: "6. 责任限制", body: "在适用法律允许的最大范围内，本应用开发者不对因使用或无法使用本应用、依赖其中任何信号或数据、或第三方服务运行而产生的任何直接、间接、附带、特殊、后果性或惩罚性损害承担责任，包括交易或投资损失、利润损失、数据丢失或业务中断。你使用本应用风险自负。本协议不限制依适用法律不得限制的责任。"),
        S(id: 7, title: "7. 第三方服务", body: "本应用连接到开发者无法控制的服务：Yahoo Finance、Binance、Coinbase、Kraken、CoinGecko、Nasdaq、圣路易斯联邦储备银行（FRED）、欧洲中央银行、ExchangeRate-API、CBOE 和美国财政部数据、新闻源、公共以太坊 RPC 提供商（publicnode.com、llamarpc.com、ankr.com）、mempool.space、公共 Solana RPC、toncenter.com、tonapi.io、Binance 账户 API（仅使用你添加的只读密钥），以及（仅在你开启时）你选择的 AI 服务。这些连接适用其各自的条款和隐私政策。开发者不对其可用性、内容或数据处理负责。本应用不连接开发者运营的任何服务器。Pro 许可证由 Telegram 机器人 \(Legal.bot) 发放（见同意书“操作与存储”）。"),
        S(id: 8, title: "8. 许可与限制", body: "\(app) © 2026 \(author)。保留所有权利。你获得在自有设备上使用本应用的个人、非独占、不可转让的许可。不得将本应用用于任何非法目的、向他人提供投资服务，或以违反其所依赖数据来源条款的方式使用。"),
        S(id: 9, title: "9. 变更与终止", body: "开发者可能更新本应用和本协议。文本变更时，本应用会在你继续使用前请你接受新版本。你可随时退出并删除本应用以停止使用，也可在 设置 ▸ 关于 中撤回同意。"),
        S(id: 10, title: "10. 联系方式", body: "本应用由 \(author) 开发。关于本协议、付款或你的数据的问题，请通过 Telegram 联系 \(Legal.contact(or: "或电子邮件"))。"),
        S(id: 12, title: "11. 付款与退款", body: "订阅通过机器人 \(Legal.bot) 以 Telegram Stars 出售。如需退款或遇到付款问题，请向 \(Legal.bot) 发送 /paysupport，或联系 \(Legal.contact(or: "或"))。Stars 按 Telegram 的规则通过 Telegram 退还。付款被退还后，订阅功能的访问随即终止。"),
        S(id: 13, title: "12. AI 提供商", body: "AI 新闻摘要默认关闭。如果你开启并选择提供商（Pollinations、Groq、Google Gemini、OpenRouter，或在你自己的 Mac 上运行的 Ollama），资产名称及其最新新闻标题（标题、发布方、日期）会发送给该提供商以生成摘要。适用该提供商自己的条款和隐私政策。你的投资组合、钱包、交易所密钥、日志和设置从不发送。你可随时在 设置 ▸ 助手 中关闭摘要。"),
        S(id: 11, title: "语言", body: "此为方便阅读的译文。如有不一致，以英文版本为准。"),
    ]

    static let consent: [Legal.Section] = [
        S(id: 101, title: "同意", body: "勾选同意框，即表示你自由、具体、知情且明确地同意 \(app) 的开发者按以下条款处理你的个人数据，包括在适用时依据欧盟《通用数据保护条例》（GDPR）、英国 GDPR 和《加州消费者隐私法》（CCPA）。"),
        S(id: 102, title: "处理的数据", body: "• 你输入的公开以太坊钱包地址（如有）。公开地址在某些情况下可能与真实个人关联，因此视为个人数据。\n• 应用设置：货币、关注的股票和加密货币交易对、外观以及所选 AI 提供商。你输入的 API 密钥保存在 macOS 钥匙串中。\n• 你的交易日志：你写下的笔记、交易、价格和标签。\n• 本地市场数据：价格历史、信号变化、引擎报告和缓存的 AI 回答。\n• 记录错误和事件的应用日志（可在 设置 ▸ 日志记录 中关闭并清除）。\n• 你接受协议的日期和版本。\n• 如果你购买 Pro：你的 Telegram ID、付款记录以及你发送给机器人的 Mac 代码（Mac 硬件标识符单向哈希的前 16 个字符），由机器人保存以发放许可证。\n• 应用联网时必然传输的技术数据，例如你的 IP 地址，第 7 节所列服务可以看到。"),
        S(id: 103, title: "目的", body: "显示价格；计算信号、概率和计划；保存你的日志；显示你选择关注的地址余额；记住你的设置；通过应用日志帮助排查问题；记录你已接受本协议。"),
        S(id: 104, title: "操作与存储", body: "收集、记录、存储、使用、传输和删除。所有数据都保留在你的 Mac 上：应用偏好设置、~/Library/Application Support/FinanceIsland（数据库、日志、报告）、~/Library/Logs/FinanceIsland（应用日志）以及钥匙串。设置 ▸ 日志记录 会显示每个文件夹及其大小。本应用不向开发者发送任何数据。如果你购买 Pro，Telegram 机器人 \(Legal.bot) 会保存你的 Telegram ID、付款记录和最多两个 Mac 代码，用于签发离线许可证；许可证在你的 Mac 上离线校验。你的投资组合、钱包地址、交易所密钥、日志和设置从不发送给机器人。钱包地址仅发送给第 7 节所列的以太坊 RPC 提供商以查询余额。开启 AI 新闻摘要时，资产名称和公开新闻标题会发送给你选择的 AI 服务（第 12 节）；你的日志、钱包地址和设置从不发送。数据不会被出售或用于广告。"),
        S(id: 105, title: "期限与撤回", body: "本同意在你撤回前一直有效。你可随时在 设置 ▸ 关于 ▸ 撤回同意 中撤回：本应用会立即删除其存储的所有数据（包括你的日志）并返回欢迎界面。删除本应用也会终止处理。你有权访问、更正和删除你的数据，可直接在本应用中完成。"),
    ]
}

enum LegalES {
    static let agreement: [Legal.Section] = [
        S(id: 1, title: "1. Aceptación", body: "Este Acuerdo de usuario (el «Acuerdo») regula el uso de \(app) (la «App»). Al hacer clic en «Aceptar y continuar» confirmas que has leído y entendido este Acuerdo y que aceptas quedar vinculado por él. Si no estás de acuerdo, no uses la App y ciérrala. Confirmas que eres mayor de edad y tienes plena capacidad legal para aceptar este Acuerdo según las leyes de tu país."),
        S(id: 2, title: "2. Qué hace la App", body: "La App muestra precios de divisas, acciones y criptomonedas obtenidos de fuentes de terceros; un Asistente que convierte precios recientes en señales de momento (BUY, SELL como operación corta, o HOLD), probabilidades, escenarios de precio simulados, niveles de stop y objetivo y un tamaño de posición sugerido; un diario del trader; opcionalmente titulares de noticias y resúmenes de un servicio de IA que elijas; y, si lo eliges, los saldos de direcciones públicas de monederos (incluido el monedero TON de Wallet en Telegram) y de una cuenta de Binance con una clave de solo lectura. La App es de solo lectura: no es un bróker, nunca pide claves privadas, frases semilla, contraseñas ni datos bancarios, no puede enviar órdenes ni firmar transacciones y no puede mover fondos. Wallet en Telegram no tiene una API de solo lectura, así que la App nunca se conecta a una cuenta de Wallet; las posiciones de Wallet Perps solo llegan de archivos que tú pones en la carpeta Bandeja de entrada de la App."),
        S(id: 3, title: "3. No es asesoramiento financiero", body: "Todo lo que muestra la App es información general generada por modelos automáticos. No es asesoramiento financiero, de inversión, fiscal ni legal, ni una oferta, ni una recomendación de comprar, vender, vender en corto o mantener ningún activo. Las señales, probabilidades, escenarios, niveles y tamaños de posición son estimaciones calculadas a partir de precios pasados con reglas mecánicas fijas y simulaciones aleatorias; no conocen tus objetivos, finanzas ni tolerancia al riesgo, pueden equivocarse y el comportamiento pasado no predice resultados futuros. El trading intradía y la venta en corto son especialmente arriesgados: los precios pueden moverse rápido, un hueco puede saltar un stop y puedes perder más de lo esperado. Los precios pueden estar retrasados, incompletos o ser inexactos y diferir de los de tu banco, bróker o bolsa. Los resúmenes de IA pueden ser erróneos o estar desactualizados. Verifica siempre la información con una fuente fiable, considera consultar a un asesor autorizado y arriesga solo dinero que puedas permitirte perder."),
        S(id: 4, title: "4. Tus decisiones", body: "Solo tú decides si operar y cómo. Cualquier orden la envías tú, con el bróker o la bolsa que elijas y según sus condiciones. La App no vigila tus posiciones ni te avisará cuando se alcance un stop o un objetivo."),
        S(id: 5, title: "5. Sin garantía", body: "La App se proporciona «tal cual» y «según disponibilidad», sin garantías de ningún tipo, expresas o implícitas, incluidas las de exactitud, integridad, actualidad, comerciabilidad, idoneidad para un fin concreto o funcionamiento ininterrumpido. Las fuentes de datos pueden cambiar, retrasarse o dejar de funcionar en cualquier momento."),
        S(id: 6, title: "6. Limitación de responsabilidad", body: "En la máxima medida permitida por la ley aplicable, el desarrollador de la App no será responsable de daños directos, indirectos, incidentales, especiales, consecuentes o punitivos, incluidas pérdidas de trading o inversión, lucro cesante, pérdida de datos o interrupción de actividad, derivados del uso o la imposibilidad de uso de la App, de confiar en cualquier señal o dato mostrado o del funcionamiento de servicios de terceros. Usas la App bajo tu propio riesgo. Nada en este Acuerdo limita la responsabilidad que no pueda limitarse según la ley aplicable."),
        S(id: 7, title: "7. Servicios de terceros", body: "La App se conecta a servicios que el desarrollador no controla: Yahoo Finance, Binance, Coinbase, Kraken, CoinGecko, Nasdaq, el Banco de la Reserva Federal de St. Louis (FRED), el Banco Central Europeo, ExchangeRate-API, datos de CBOE y del Tesoro de EE. UU., fuentes de noticias, proveedores RPC públicos de Ethereum (publicnode.com, llamarpc.com, ankr.com), mempool.space, el RPC público de Solana, toncenter.com, tonapi.io, la API de cuenta de Binance (solo con una clave de lectura que añadas) y, solo si lo activas, el servicio de IA que elijas. A esas conexiones se aplican sus propios términos y políticas de privacidad. El desarrollador no responde de su disponibilidad, contenido o tratamiento de datos. La App no se conecta a ningún servidor del desarrollador. Las licencias Pro las emite el bot de Telegram \(Legal.bot) (ver el Consentimiento, «Operaciones y almacenamiento»)."),
        S(id: 8, title: "8. Licencia y restricciones", body: "\(app) es © 2026 \(author). Todos los derechos reservados. Se te concede una licencia personal, no exclusiva e intransferible para usar la App en tus propios dispositivos. No puedes usar la App con fines ilícitos, para ofrecer servicios de inversión a terceros ni de forma que infrinja los términos de las fuentes de datos en las que se basa."),
        S(id: 9, title: "9. Cambios y terminación", body: "El desarrollador puede actualizar la App y este Acuerdo. Cuando cambie el texto, la App te pedirá aceptar la nueva versión antes de continuar. Puedes dejar de usar la App en cualquier momento cerrándola y eliminándola, y retirar tu consentimiento en Ajustes ▸ Acerca de."),
        S(id: 10, title: "10. Contacto", body: "La App está desarrollada por \(author). Preguntas sobre este Acuerdo, los pagos o tus datos: Telegram \(Legal.contact(or: "o correo"))."),
        S(id: 12, title: "11. Pagos y reembolsos", body: "Las suscripciones se venden por Telegram Stars a través del bot \(Legal.bot). Para un reembolso o un problema de pago, envía /paysupport a \(Legal.bot) o escribe a \(Legal.contact(or: "o")). Las Stars se reembolsan a través de Telegram según sus normas. El acceso a las funciones de suscriptor termina cuando se reembolsa un pago."),
        S(id: 13, title: "12. Proveedores de IA", body: "Los resúmenes de noticias con IA están desactivados por defecto. Si los activas y eliges un proveedor (Pollinations, Groq, Google Gemini, OpenRouter u Ollama en tu propio Mac), el nombre del activo y sus últimos titulares (título, medio, fecha) se envían a ese proveedor para redactar el resumen. Se aplican sus propios términos y política de privacidad. Tu cartera, monederos, claves de exchange, diario y ajustes nunca se envían. Puedes desactivar los resúmenes en cualquier momento en Ajustes ▸ Asistente."),
        S(id: 11, title: "Idioma", body: "Esta es una traducción de cortesía. En caso de discrepancia prevalece la versión en inglés."),
    ]

    static let consent: [Legal.Section] = [
        S(id: 101, title: "Consentimiento", body: "Al marcar la casilla de consentimiento das, de forma libre, específica, informada e inequívoca, tu consentimiento para que el desarrollador de \(app) trate tus datos personales en los términos siguientes, incluido, cuando proceda, conforme al Reglamento General de Protección de Datos de la UE (RGPD), el RGPD del Reino Unido y la Ley de Privacidad del Consumidor de California (CCPA)."),
        S(id: 102, title: "Datos tratados", body: "• La dirección pública de cartera de Ethereum que introduzcas, si la hay. En algunos casos una dirección pública puede vincularse a una persona real, por lo que se trata como dato personal.\n• Los ajustes de la App: divisas, acciones y pares cripto vigilados, apariencia y el proveedor de IA elegido. Las claves API que introduzcas se guardan en el llavero de macOS.\n• Tu diario del trader: las notas, operaciones, precios y etiquetas que escribas.\n• Datos de mercado locales: historial de precios, cambios de señal, informes del motor y respuestas de IA en caché.\n• Un registro de la app con errores y eventos (puede desactivarse y borrarse en Ajustes ▸ Registros).\n• La fecha y versión del Acuerdo que aceptaste.\n• Si compras Pro: tu ID de Telegram, tus pagos y el código de Mac que envías al bot (los primeros 16 caracteres de un hash unidireccional del identificador de hardware de tu Mac), que el bot guarda para emitir licencias.\n• Datos técnicos que se transmiten necesariamente al conectarse a internet, como tu dirección IP, visible para los servicios de la sección 7."),
        S(id: 103, title: "Finalidades", body: "Mostrar precios, calcular señales, probabilidades y planes, llevar tu diario, mostrar el saldo de la dirección que elegiste vigilar, recordar tus ajustes, ayudar a encontrar problemas mediante el registro de la app y dejar constancia de que aceptaste este Acuerdo."),
        S(id: 104, title: "Operaciones y almacenamiento", body: "Recogida, registro, almacenamiento, uso, transferencia y supresión. Todos los datos permanecen en tu Mac: en las preferencias de la App, en ~/Library/Application Support/FinanceIsland (base de datos, diario, informes), en ~/Library/Logs/FinanceIsland (registro de la app) y en el llavero. Ajustes ▸ Registros muestra cada carpeta y su tamaño. La App no envía nada al desarrollador. Si compras Pro, el bot de Telegram \(Legal.bot) guarda tu ID de Telegram, tus pagos y hasta dos códigos de Mac para firmar licencias sin conexión; la licencia se comprueba en tu Mac sin red. Tu cartera, direcciones de monedero, claves de exchange, diario y ajustes nunca se envían al bot. La dirección de la cartera solo se envía a los proveedores RPC de Ethereum de la sección 7 para consultar su saldo. Con los resúmenes de noticias con IA activados, se envían al servicio de IA elegido el nombre del activo y sus titulares públicos (sección 12); tu diario, tu dirección y tus ajustes nunca se envían. Los datos no se venden ni se usan para publicidad."),
        S(id: 105, title: "Duración y retirada", body: "Este consentimiento es válido hasta que lo retires. Puedes retirarlo en cualquier momento en Ajustes ▸ Acerca de ▸ Retirar consentimiento: la App eliminará de inmediato todos los datos guardados, incluido tu diario, y volverá a la pantalla de bienvenida. Eliminar la App también pone fin al tratamiento. Tienes derecho a acceder, rectificar y suprimir tus datos, lo que puedes hacer directamente en la App."),
    ]
}

enum LegalDE {
    static let agreement: [Legal.Section] = [
        S(id: 1, title: "1. Annahme", body: "Diese Nutzungsvereinbarung („Vereinbarung“) regelt deine Nutzung von \(app) („die App“). Mit einem Klick auf „Akzeptieren und fortfahren“ bestätigst du, dass du diese Vereinbarung gelesen und verstanden hast und ihr zustimmst. Wenn du nicht einverstanden bist, nutze die App nicht und beende sie. Du bestätigst, dass du volljährig und nach dem Recht deines Landes voll geschäftsfähig bist."),
        S(id: 2, title: "2. Was die App tut", body: "Die App zeigt Kurse von Währungen, Aktien und Kryptowährungen aus Drittquellen; einen Assistenten, der aktuelle Kurse in Momentum-Signale (BUY, SELL als Short-Trade oder HOLD), Wahrscheinlichkeiten, simulierte Kursszenarien, Stop- und Zielmarken sowie eine vorgeschlagene Positionsgröße umsetzt; ein Trading-Journal; optional Schlagzeilen und Zusammenfassungen eines von dir gewählten KI-Dienstes; und, wenn du möchtest, die Guthaben öffentlicher Wallet-Adressen (auch der TON-Wallet aus Wallet in Telegram) und eines Binance-Kontos über einen Nur-Lese-Schlüssel. Die App ist rein lesend: Sie ist kein Broker, fragt nie nach privaten Schlüsseln, Seed-Phrasen, Passwörtern oder Bankdaten, kann keine Orders platzieren oder Transaktionen signieren und kein Geld bewegen. Wallet in Telegram hat keine Nur-Lese-API, daher verbindet sich die App nie mit einem Wallet-Konto; Wallet-Perps-Positionen kommen nur aus Dateien, die du in den Eingangsordner der App legst."),
        S(id: 3, title: "3. Keine Finanzberatung", body: "Alles, was die App zeigt, sind allgemeine Informationen aus automatischen Modellen. Es ist keine Finanz-, Anlage-, Steuer- oder Rechtsberatung, kein Angebot und keine Empfehlung, einen Wert zu kaufen, zu verkaufen, leerzuverkaufen oder zu halten. Signale, Wahrscheinlichkeiten, Szenarien, Marken und Positionsgrößen sind Schätzungen aus vergangenen Kursen mit festen mechanischen Regeln und Zufallssimulationen; sie kennen deine Ziele, Finanzen und Risikobereitschaft nicht, können falsch sein, und vergangenes Verhalten sagt keine künftigen Ergebnisse voraus. Intraday-Handel und Leerverkäufe sind besonders riskant: Kurse können sich schnell bewegen, eine Lücke kann über einen Stop springen, und du kannst mehr verlieren als erwartet. Kurse können verzögert, unvollständig oder ungenau sein und von denen deiner Bank, deines Brokers oder deiner Börse abweichen. KI-Zusammenfassungen können falsch oder veraltet sein. Prüfe Informationen immer bei einer verlässlichen Quelle, erwäge eine lizenzierte Beratung und riskiere nur Geld, dessen Verlust du verkraften kannst."),
        S(id: 4, title: "4. Deine Entscheidungen", body: "Nur du entscheidest, ob und wie du handelst. Jede Order platzierst du selbst bei einem Broker oder einer Börse deiner Wahl zu deren Bedingungen. Die App überwacht deine Positionen nicht und warnt dich nicht, wenn ein Stop oder Ziel erreicht wird."),
        S(id: 5, title: "5. Keine Gewährleistung", body: "Die App wird „wie besehen“ und „wie verfügbar“ bereitgestellt, ohne ausdrückliche oder stillschweigende Gewährleistung, einschließlich Richtigkeit, Vollständigkeit, Aktualität, Marktgängigkeit, Eignung für einen bestimmten Zweck oder unterbrechungsfreien Betrieb. Datenquellen können sich jederzeit ändern, verzögern oder ausfallen."),
        S(id: 6, title: "6. Haftungsbeschränkung", body: "Soweit nach geltendem Recht zulässig, haftet der Entwickler der App nicht für direkte, indirekte, zufällige, besondere, Folge- oder Strafschäden, einschließlich Handels- oder Anlageverlusten, entgangenem Gewinn, Datenverlust oder Betriebsunterbrechung, die aus der Nutzung oder Nichtnutzbarkeit der App, dem Vertrauen auf darin gezeigte Signale oder Daten oder dem Betrieb von Drittdiensten entstehen. Du nutzt die App auf eigenes Risiko. Nichts in dieser Vereinbarung beschränkt eine Haftung, die nach geltendem Recht nicht beschränkt werden kann."),
        S(id: 7, title: "7. Drittdienste", body: "Die App verbindet sich mit Diensten, die der Entwickler nicht kontrolliert: Yahoo Finance, Binance, Coinbase, Kraken, CoinGecko, Nasdaq, die Federal Reserve Bank of St. Louis (FRED), die Europäische Zentralbank, ExchangeRate-API, CBOE- und US-Treasury-Daten, Nachrichtenquellen, öffentliche Ethereum-RPC-Anbieter (publicnode.com, llamarpc.com, ankr.com), mempool.space, der öffentliche Solana-RPC, toncenter.com, tonapi.io, die Binance-Konto-API (nur mit einem von dir hinzugefügten Lese-Schlüssel) und, nur wenn du es einschaltest, den von dir gewählten KI-Dienst. Für diese Verbindungen gelten deren eigene Bedingungen und Datenschutzrichtlinien. Der Entwickler ist für deren Verfügbarkeit, Inhalte oder Datenverarbeitung nicht verantwortlich. Die App verbindet sich mit keinem Server des Entwicklers. Pro-Lizenzen kommen vom Telegram-Bot \(Legal.bot) (siehe Einwilligung, „Vorgänge und Speicherung“)."),
        S(id: 8, title: "8. Lizenz und Einschränkungen", body: "\(app) ist © 2026 \(author). Alle Rechte vorbehalten. Du erhältst eine persönliche, nicht ausschließliche, nicht übertragbare Lizenz, die App auf deinen eigenen Geräten zu nutzen. Du darfst die App nicht für rechtswidrige Zwecke, zum Anbieten von Anlagedienstleistungen für andere oder entgegen den Bedingungen der genutzten Datenquellen verwenden."),
        S(id: 9, title: "9. Änderungen und Beendigung", body: "Der Entwickler kann die App und diese Vereinbarung aktualisieren. Ändert sich der Text, bittet dich die App vor der weiteren Nutzung, die neue Version zu akzeptieren. Du kannst die Nutzung jederzeit beenden, indem du die App schließt und löschst, und deine Einwilligung unter Einstellungen ▸ Über widerrufen."),
        S(id: 10, title: "10. Kontakt", body: "Die App wird von \(author) entwickelt. Fragen zu dieser Vereinbarung, zu Zahlungen oder deinen Daten: Telegram \(Legal.contact(or: "oder E-Mail"))."),
        S(id: 12, title: "11. Zahlungen und Erstattungen", body: "Abos werden über den Bot \(Legal.bot) gegen Telegram Stars verkauft. Für eine Erstattung oder ein Zahlungsproblem sende /paysupport an \(Legal.bot) oder schreibe an \(Legal.contact(or: "oder")). Stars werden über Telegram nach dessen Regeln erstattet. Der Zugang zu Abo-Funktionen endet, wenn eine Zahlung erstattet wird."),
        S(id: 13, title: "12. KI-Anbieter", body: "KI-Nachrichtenzusammenfassungen sind standardmäßig aus. Wenn du sie einschaltest und einen Anbieter wählst (Pollinations, Groq, Google Gemini, OpenRouter oder Ollama auf deinem eigenen Mac), werden der Name des Werts und seine neuesten Schlagzeilen (Titel, Quelle, Datum) an diesen Anbieter gesendet, um die Zusammenfassung zu schreiben. Es gelten dessen eigene Bedingungen und Datenschutzrichtlinien. Dein Portfolio, Wallets, Börsenschlüssel, Journal und Einstellungen werden nie gesendet. Du kannst die Zusammenfassungen jederzeit unter Einstellungen ▸ Assistent ausschalten."),
        S(id: 11, title: "Sprache", body: "Dies ist eine Übersetzung zur Information. Bei Abweichungen gilt die englische Fassung."),
    ]

    static let consent: [Legal.Section] = [
        S(id: 101, title: "Einwilligung", body: "Mit dem Ankreuzen des Kästchens willigst du freiwillig, für den bestimmten Fall, in informierter Weise und unmissverständlich in die Verarbeitung deiner personenbezogenen Daten durch den Entwickler von \(app) zu den folgenden Bedingungen ein, gegebenenfalls auch nach der EU-Datenschutz-Grundverordnung (DSGVO), der UK-DSGVO und dem California Consumer Privacy Act (CCPA)."),
        S(id: 102, title: "Verarbeitete Daten", body: "• Die öffentliche Ethereum-Wallet-Adresse, falls du eine eingibst. Eine öffentliche Adresse kann in manchen Fällen einer realen Person zugeordnet werden und gilt daher als personenbezogenes Datum.\n• Deine App-Einstellungen: Währungen, beobachtete Aktien und Krypto-Paare, Darstellung und der gewählte KI-Anbieter. Eingegebene API-Schlüssel liegen im macOS-Schlüsselbund.\n• Dein Trading-Journal: die Notizen, Trades, Kurse und Tags, die du schreibst.\n• Lokale Marktdaten: Kurshistorie, Signalwechsel, Engine-Berichte und zwischengespeicherte KI-Antworten.\n• Ein App-Protokoll mit Fehlern und Ereignissen (abschaltbar und löschbar unter Einstellungen ▸ Protokolle).\n• Datum und Version der akzeptierten Vereinbarung.\n• Wenn du Pro kaufst: deine Telegram-ID, deine Zahlungen und der Mac-Code, den du an den Bot sendest (die ersten 16 Zeichen eines Einweg-Hashs der Hardwarekennung deines Macs), den der Bot zum Ausstellen von Lizenzen speichert.\n• Technische Daten, die bei einer Internetverbindung zwangsläufig übertragen werden, etwa deine IP-Adresse, die für die Dienste aus Abschnitt 7 sichtbar ist."),
        S(id: 103, title: "Zwecke", body: "Kurse anzeigen, Signale, Wahrscheinlichkeiten und Pläne berechnen, dein Journal führen, das Guthaben der gewählten Adresse anzeigen, deine Einstellungen speichern, Probleme über das App-Protokoll finden und festhalten, dass du diese Vereinbarung akzeptiert hast."),
        S(id: 104, title: "Vorgänge und Speicherung", body: "Erhebung, Erfassung, Speicherung, Nutzung, Übermittlung und Löschung. Alle Daten bleiben auf deinem Mac: in den Einstellungen der App, in ~/Library/Application Support/FinanceIsland (Datenbank, Journal, Berichte), in ~/Library/Logs/FinanceIsland (App-Protokoll) und im Schlüsselbund. Einstellungen ▸ Protokolle zeigt jeden Ordner und seine Größe. Die App sendet nichts an den Entwickler. Wenn du Pro kaufst, speichert der Telegram-Bot \(Legal.bot) deine Telegram-ID, deine Zahlungen und bis zu zwei Mac-Codes, um Offline-Lizenzen zu signieren; die Lizenz wird auf deinem Mac ohne Netzwerk geprüft. Dein Portfolio, Wallet-Adressen, Börsenschlüssel, Journal und Einstellungen werden nie an den Bot gesendet. Die Wallet-Adresse wird nur an die Ethereum-RPC-Anbieter aus Abschnitt 7 gesendet, um ihr Guthaben abzufragen. Sind KI-Nachrichtenzusammenfassungen aktiv, werden Name des Werts und öffentliche Schlagzeilen an den gewählten KI-Dienst gesendet (Abschnitt 12); dein Journal, deine Adresse und deine Einstellungen nie. Daten werden weder verkauft noch für Werbung genutzt."),
        S(id: 105, title: "Dauer und Widerruf", body: "Diese Einwilligung gilt bis zu ihrem Widerruf. Du kannst sie jederzeit unter Einstellungen ▸ Über ▸ Einwilligung widerrufen zurücknehmen: Die App löscht sofort alle gespeicherten Daten einschließlich deines Journals und kehrt zum Willkommensbildschirm zurück. Das Löschen der App beendet die Verarbeitung ebenfalls. Du hast das Recht auf Auskunft, Berichtigung und Löschung deiner Daten, was du direkt in der App erledigen kannst."),
    ]
}
